                    emon.Port.CellsSet(nfw, (r * 24) + Evidence.WfGap(), v);
                } else {
                    v = emon.Port.CellsAt(ofw, (tl * 24) + Evidence.WfWbreak());
                    emon.Port.CellsSet(nfw, (r * 24) + Evidence.WfWbreak(), v);
                    v = emon.Port.CellsAt(ofw, (tl * 24) + Evidence.WfGap());
                    emon.Port.CellsSet(nfw, (r * 24) + Evidence.WfGap(), v);
                }
            }
            ArPutFv(fv, g, Model.SrOcr(), number, conf, flags);
            j += 1;
        }
        return no;
    }
    internal static int ArWordSource(emon.Port.Cells ofw, int w) {
        // The source a word stands for when no group decided it: `ocr` for an OCR line's word, `hidden-text`, else `text`.
        int s = emon.Port.CellsAt(ofw, (w * 24) + Evidence.WfSrc());
        if ((s & Model.SrOcr()) != 0) {
            return Model.SrOcr();
        }
        if ((s & Model.SrHiddenText()) != 0) {
            return Model.SrHiddenText();
        }
        return Model.SrText();
    }
    internal static int ArFlushOcrOnly(int page, emon.Port.Cells cg, emon.Port.Cells refs, emon.Port.Cells etext, emon.Port.Cells owords, emon.Port.Cells olines, emon.Port.Cells oruns, emon.Port.Cells osyms, emon.Port.Cells gd, emon.Port.Cells o2g, emon.Port.Cells nfw, emon.Port.Cells nfl, emon.Port.Cells fv, emon.Port.Cells tw, emon.Port.Cells tl, emon.Port.Cells scr) {
        // The admitted OCR-only words of `page`, each OCR line's own as a line of the fused flow, measured as an OCR line is (D213).
        int nr = Evidence.OrCount(oruns);
        int r = 0;
        int l0 = 0;
        int nl = 0;
        int rotmed = 0;
        int l = 0;
        int tli = 0;
        int cnt = 0;
        int w0 = 0;
        int j = 0;
        int orow = 0;
        int g = 0;
        int twr = 0;
        int first = 0;
        int kept = 0;
        int lrow = 0;
        int trow = 0;
        int made = 0;
        int nrow = 0;
        while (r < nr) {
            if (Evidence.OrGet(oruns, r, Evidence.OrfPage()) == page) {
                l0 = Evidence.OrGet(oruns, r, Evidence.OrfLfirst());
                nl = Evidence.OrGet(oruns, r, Evidence.OrfLcount());
                rotmed = Evidence.EvRotMedian(olines, l0, nl);
                emon.Port.CellsDrop(tw, 0);
                emon.Port.CellsDrop(tl, 0);
                Scan.ScPrep(scr);
                Scan.ScEmitLines(olines, owords, osyms, l0, nl, page, rotmed, scr, tw, tl);
                l = l0;
                tli = 0;
                twr = 0;
                while (l < (l0 + nl)) {
                    cnt = Evidence.OlGet(olines, l, Evidence.LhCount());
                    if (cnt > 0) {
                        w0 = Evidence.OlGet(olines, l, Evidence.LhFirst());
                        first = Player.FwCount(nfw);
                        lrow = Player.FlCount(nfl);
                        kept = 0;
                        j = 0;
                        while (j < cnt) {
                            orow = w0 + j;
                            g = emon.Port.CellsAt(o2g, orow);
                            if (g >= 0) {
                                if ((emon.Port.CellsAt(gd, (g * 10) + 2) == Fuserules.FwOcr()) && ((Player.CgGet(cg, g, Player.CgfTcount()) == 0) && (Player.CgGet(cg, g, Player.CgfHcount()) == 0))) {
                                    trow = twr + j;
                                    nrow = Player.FwCopyWord(nfw, tw, trow, lrow);
                                    emon.Port.CellsSet(nfw, (nrow * 24) + Evidence.WfSrc(), emon.Port.CellsAt(gd, (g * 10) + 7));
                                    Player.FvNew(fv, g, Model.SrOcr(), emon.Port.CellsAt(gd, (g * 10) + 1), emon.Port.CellsAt(gd, (g * 10) + 3), emon.Port.CellsAt(gd, (g * 10) + 4));
                                    kept += 1;
                                }
                            }
                            j += 1;
                        }
                        if (kept > 0) {
                            Player.FlCopyLine(nfl, tl, tli, first, kept);
                            if (kept < cnt) {
                                ArRemeasure(nfl, nfw, lrow, first, kept);
                            }
                            made += 1;
                        }
                        twr += cnt;
                        tli += 1;
                    }
                    l += 1;
                }
            }
            r += 1;
        }
        return made;
    }
    internal static int ArPageAgreement(emon.Port.Cells cg, int g0, int g1, emon.Port.Cells refs, emon.Port.Cells ofw, emon.Port.Cells etext) {
        // How far the engine can be trusted on a page (per mille), from the groups [g0, g1) of that page. Of the groups with a visible
        // text-layer candidate and an OCR candidate, the share whose case-folded similarity is at least `agree-sim`, in ANY script (an
        // engine that cannot read the page agrees with nothing); 1000 when fewer than three groups have both. And 0 when 30 per cent or more of
        // the page's text-layer words are in a script the engine lacks (it cannot read what it was not trained on, whatever it says).
        int g = g0;
        int both = 0;
        int agree = 0;
        int k = 0;
        int words = 0;
        int foreign = 0;
        while (g < g1) {
            if ((Player.CgGet(cg, g, Player.CgfTcount()) > 0) && (Player.CgGet(cg, g, Player.CgfOcount()) > 0)) {
                both += 1;
                if (Player.CgGet(cg, g, Player.CgfSimfold()) >= Health.HhAgreeSim()) {
                    agree += 1;
                }
            }
            k = 0;
            while (k < Player.CgGet(cg, g, Player.CgfTcount())) {
                words += 1;
                if (ArWordLatin(ofw, etext, ArRef(refs, Player.CgGet(cg, g, Player.CgfTfirst()) + k, 1)) == 0) {
                    foreign += 1;
                }
                k += 1;
            }
            g += 1;
        }
        if ((words > 0) && ((foreign * 10) >= (words * 3))) {
            return 0;
        }
        if (both < 3) {
            return 1000;
        }
        return (agree * 1000) / both;
    }
    public static int ArDoc(emon.Port.Cells cg, emon.Port.Cells refs, emon.Port.Cells ofw, emon.Port.Cells ofl, emon.Port.Cells etext, emon.Port.Cells feats, emon.Port.Cells owords, emon.Port.Cells olines, emon.Port.Cells oruns, emon.Port.Cells osyms, emon.Port.Cells images, emon.Port.Cells epages, emon.Port.Cells nfw, emon.Port.Cells nfl, emon.Port.Cells fv, emon.Port.Cells fx, emon.Port.Cells afa, emon.Port.Cells gd, emon.Port.Cells gv, emon.Port.Cells w2g, emon.Port.Cells o2g, emon.Port.Cells pp, emon.Port.Cells tw, emon.Port.Cells tl, emon.Port.Cells scr) {
        // See the head of this file. The new arenas and the scratch are the caller's (any contents; they are emptied here).
        int ng = Player.CgCount(cg);
        int nofw = Player.FwCount(ofw);
        int nofl = Player.FlCount(ofl);
        int now = Evidence.OwCount(owords);
        int i = 0;
        int k = 0;
        int g = 0;
        int l = 0;
        int w = 0;
        int wend = 0;
        int page = 0;
        int cur = -1;
        int first = 0;
        int lrow = 0;
        int changed = 0;
        int @base = 0;
        int win = 0;
        int r = 0;
        int s = 0;
        int np = 0;
        int pend = 0;
        emon.Port.CellsDrop(nfw, 0);
        emon.Port.CellsDrop(nfl, 0);
        emon.Port.CellsDrop(fv, 0);
        emon.Port.CellsDrop(fx, 0);
        emon.Port.CellsDrop(afa, 0);
        emon.Port.CellsDrop(gd, 0);
        emon.Port.CellsDrop(gv, 0);
        emon.Port.CellsDrop(w2g, 0);
        emon.Port.CellsDrop(o2g, 0);
        emon.Port.CellsDrop(pp, 0);
        i = 0;
        while (i < Fuserules.AgCount()) {
            emon.Port.CellsPush(gv, 0);
            i += 1;
        }
        i = 0;
        while (i < nofw) {
            emon.Port.CellsPush(w2g, -1);
            i += 1;
        }
        i = 0;
        while (i < now) {
            emon.Port.CellsPush(o2g, -1);
            i += 1;
        }
        i = 0;
        while (i < (ng * 10)) {
            emon.Port.CellsPush(gd, 0);
            i += 1;
        }
        // the agreement of each group's page with OCR, before any group is decided (a page where the engine and the text layer do not agree
        // is a page whose OCR-only words are not to be admitted)
        g = 0;
        while (g < ng) {
            k = g;
            while ((k < ng) && (Player.CgGet(cg, k, Player.CgfPage()) == Player.CgGet(cg, g, Player.CgfPage()))) {
                k += 1;
            }
            s = ArPageAgreement(cg, g, k, refs, ofw, etext);
            i = g;
            while (i < k) {
                emon.Port.CellsSet(gd, (i * 10) + 8, s);
                i += 1;
            }
            g = k;
        }
        // the map from a word to its group, and from an OCR word to its group
        g = 0;
        while (g < ng) {
            k = 0;
            while (k < Player.CgGet(cg, g, Player.CgfTcount())) {
                r = ArRef(refs, Player.CgGet(cg, g, Player.CgfTfirst()) + k, 1);
                emon.Port.CellsSet(w2g, r, g);
                k += 1;
            }
            k = 0;
            while (k < Player.CgGet(cg, g, Player.CgfHcount())) {
                r = ArRef(refs, Player.CgGet(cg, g, Player.CgfHfirst()) + k, 1);
                emon.Port.CellsSet(w2g, r, g);
                k += 1;
            }
            k = 0;
            while (k < Player.CgGet(cg, g, Player.CgfOcount())) {
                r = ArRef(refs, Player.CgGet(cg, g, Player.CgfOfirst()) + k, 1);
                emon.Port.CellsSet(o2g, r, g);
                k += 1;
            }
            ArFill(g, emon.Port.CellsAt(gd, (g * 10) + 8), cg, refs, ofw, etext, feats, owords, images, epages, gv);
            ArDecide(g, cg, refs, ofw, etext, feats, owords, images, epages, gv, gd, fx, afa);
            g += 1;
        }
        // the pages that have an admitted OCR-only group, ascending (a group's page; `cg` is in page order)
        g = 0;
        while (g < ng) {
            if ((emon.Port.CellsAt(gd, (g * 10) + 2) == Fuserules.FwOcr()) && ((Player.CgGet(cg, g, Player.CgfTcount()) == 0) && (Player.CgGet(cg, g, Player.CgfHcount()) == 0))) {
                page = Player.CgGet(cg, g, Player.CgfPage());
                if (page != cur) {
                    cur = page;
                    emon.Port.CellsPush(pp, page);
                }
            }
            g += 1;
        }
        pend = 0;
        cur = -1;
        l = 0;
        while (l < nofl) {
            page = emon.Port.CellsAt(ofl, l * 16);
            if (page != cur) {
                // the previous page's OCR-only lines, then every pending page before this one
                if (cur >= 0) {
                    if ((pend < emon.Port.CellsLen(pp)) && (emon.Port.CellsAt(pp, pend) == cur)) {
                        ArFlushOcrOnly(cur, cg, refs, etext, owords, olines, oruns, osyms, gd, o2g, nfw, nfl, fv, tw, tl, scr);
                        pend += 1;
                    }
                }
                while ((pend < emon.Port.CellsLen(pp)) && (emon.Port.CellsAt(pp, pend) < page)) {
                    ArFlushOcrOnly(emon.Port.CellsAt(pp, pend), cg, refs, etext, owords, olines, oruns, osyms, gd, o2g, nfw, nfl, fv, tw, tl, scr);
                    pend += 1;
                }
                cur = page;
            }
            first = Player.FwCount(nfw);
            lrow = Player.FlCount(nfl);
            changed = 0;
            w = emon.Port.CellsAt(ofl, (l * 16) + 11);
            wend = w + emon.Port.CellsAt(ofl, (l * 16) + 12);
            while (w < wend) {
                g = emon.Port.CellsAt(w2g, w);
                if (g < 0) {
                    s = ArWordSource(ofw, w);
                    ArCopyWord(nfw, ofw, w, lrow, emon.Port.CellsAt(ofw, (w * 24) + Evidence.WfSrc()));
                    if (s == Model.SrOcr()) {
                        ArPutFv(fv, -1, s, 101, 500, Model.FlOcrOnly());
                    } else {
                        ArPutFv(fv, -1, s, 101, 900, 0);
                    }
                } else {
                    @base = g * 10;
                    win = emon.Port.CellsAt(gd, @base + 2);
                    if (win == Fuserules.FwOcr()) {
                        if (emon.Port.CellsAt(gd, @base + 6) == 0) {
                            emon.Port.CellsSet(gd, @base + 6, 1);
                            ArEmitOcr(g, cg, refs, ofw, etext, owords, nfw, fv, gd, lrow);
                        }
                        changed = 1;
                    } else if (win == Fuserules.FwNone()) {
                        changed = 1;
                    } else {
                        s = ArWordSource(ofw, w);
                        r = ArCopyWord(nfw, ofw, w, lrow, emon.Port.CellsAt(ofw, (w * 24) + Evidence.WfSrc()) | emon.Port.CellsAt(gd, @base + 7));
                        ArPutFv(fv, g, s, emon.Port.CellsAt(gd, @base + 1), emon.Port.CellsAt(gd, @base + 3), emon.Port.CellsAt(gd, @base + 4));
                    }
                }
                w += 1;
            }
            np = Player.FwCount(nfw) - first;
            if (np > 0) {
                Player.FlCopyLine(nfl, ofl, l, first, np);
                if (changed == 1) {
                    ArRemeasure(nfl, nfw, lrow, first, np);
                }
            }
            l += 1;
        }
        // the last page's OCR-only lines, and the pages after it
        if ((cur >= 0) && ((pend < emon.Port.CellsLen(pp)) && (emon.Port.CellsAt(pp, pend) == cur))) {
            ArFlushOcrOnly(cur, cg, refs, etext, owords, olines, oruns, osyms, gd, o2g, nfw, nfl, fv, tw, tl, scr);
            pend += 1;
        }
        while (pend < emon.Port.CellsLen(pp)) {
            ArFlushOcrOnly(emon.Port.CellsAt(pp, pend), cg, refs, etext, owords, olines, oruns, osyms, gd, o2g, nfw, nfl, fv, tw, tl, scr);
            pend += 1;
        }
        return ng;
    }
    public static int ArWrite(emon.Port.Cells afa, emon.Port.Cells owords, emon.Port.Cells etext, emon.Port.Cells ledger, emon.Port.Cells text, emon.Port.Cells tmp, emon.Port.Cells tt) {
        // The OCR groups dropped as ghosts (`afa`) as ledger rows, after `fu-write`: a run of rows of one page and one OCR line is ONE row,
        // its box the union of theirs, its text the first words joined by a space (NFC, ligatures folded, as every ledger text), its
        // confidence 700 (an engine's reading of nothing the text layer or the ink explains), src `ocr`. Answers the rows written.
        int n = Player.FaCount(afa);
        int i = 0;
        int j = 0;
        int k = 0;
        int s = 0;
        int e = 0;
        int x0 = 0;
        int y0 = 0;
        int x1 = 0;
        int y1 = 0;
        int lr = 0;
        int t0 = 0;
        int rows = 0;
        int line = 0;
        int w = 0;
        while (i < n) {
            j = i + 1;
            if (Player.FaGet(afa, i, 6) == Evidence.EaWords()) {
                // a hidden word set aside (P7.6): a run of rows of one page whose boxes share a line (the next starts above the first's bottom) is one row, `invisible`, src `hidden-text`
                while ((j < n) && ((Player.FaGet(afa, j, 6) == Evidence.EaWords()) && ((Player.FaGet(afa, j, 0) == Player.FaGet(afa, i, 0)) && (Player.FaGet(afa, j, 2) < Player.FaGet(afa, i, 4))))) {
                    j += 1;
                }
                x0 = Player.FaGet(afa, i, 1);
                y0 = Player.FaGet(afa, i, 2);
                x1 = Player.FaGet(afa, i, 3);
                y1 = Player.FaGet(afa, i, 4);
                emon.Port.CellsDrop(tt, 0);
                k = i;
                while (k < j) {
                    if (k > i) {
                        emon.Port.CellsPush(tt, 32);
                    }
                    if (Player.FaGet(afa, k, 1) < x0) {
                        x0 = Player.FaGet(afa, k, 1);
                    }
                    if (Player.FaGet(afa, k, 2) < y0) {
                        y0 = Player.FaGet(afa, k, 2);
                    }
                    if (Player.FaGet(afa, k, 3) > x1) {
                        x1 = Player.FaGet(afa, k, 3);
                    }
                    if (Player.FaGet(afa, k, 4) > y1) {
                        y1 = Player.FaGet(afa, k, 4);
                    }
                    s = Player.FaGet(afa, k, 8);
                    e = s + Player.FaGet(afa, k, 11);
                    while (s < e) {
                        emon.Port.CellsPush(tt, emon.Port.CellsAt(etext, s));
                        s += 1;
                    }
                    k += 1;
                }
                lr = Model.LedgerAdd(ledger, Player.FaGet(afa, i, 5), Player.FaGet(afa, i, 0), x0, y0, x1, y1, 900, Model.SrHiddenText());
                t0 = emon.Port.CellsLen(text);
                Normalize.NzNfc(tt, 0, emon.Port.CellsLen(tt), text, tmp, Normalize.NzFlagLigatures() + Normalize.NzFlagRadicals());
                Model.LedgerSetText(ledger, lr, t0, emon.Port.CellsLen(text) - t0);
                rows += 1;
                i = j;
            } else {
                w = Player.FaGet(afa, i, 7);
                line = Evidence.OwGet(owords, w, Evidence.HdLine());
                while ((j < n) && ((Player.FaGet(afa, j, 6) == Evidence.EaOwords()) && ((Player.FaGet(afa, j, 0) == Player.FaGet(afa, i, 0)) && ((Player.FaGet(afa, j, 5) == Player.FaGet(afa, i, 5)) && (Evidence.OwGet(owords, Player.FaGet(afa, j, 7), Evidence.HdLine()) == line))))) {
                    j += 1;
                }
                x0 = Player.FaGet(afa, i, 1);
                y0 = Player.FaGet(afa, i, 2);
                x1 = Player.FaGet(afa, i, 3);
                y1 = Player.FaGet(afa, i, 4);
                emon.Port.CellsDrop(tt, 0);
                k = i;
                while (k < j) {
                    if (k > i) {
                        emon.Port.CellsPush(tt, 32);
                    }
                    if (Player.FaGet(afa, k, 1) < x0) {
                        x0 = Player.FaGet(afa, k, 1);
                    }
                    if (Player.FaGet(afa, k, 2) < y0) {
                        y0 = Player.FaGet(afa, k, 2);
                    }
                    if (Player.FaGet(afa, k, 3) > x1) {
                        x1 = Player.FaGet(afa, k, 3);
                    }
                    if (Player.FaGet(afa, k, 4) > y1) {
                        y1 = Player.FaGet(afa, k, 4);
                    }
                    w = Player.FaGet(afa, k, 7);
                    s = Evidence.OwGet(owords, w, Evidence.HdTstart());
                    e = s + Evidence.OwGet(owords, w, Evidence.HdTlen());
                    while (s < e) {
                        emon.Port.CellsPush(tt, emon.Port.CellsAt(etext, s));
                        s += 1;
                    }
                    k += 1;
                }
                lr = Model.LedgerAdd(ledger, Player.FaGet(afa, i, 5), Player.FaGet(afa, i, 0), x0, y0, x1, y1, 700, Model.SrOcr());
                t0 = emon.Port.CellsLen(text);
                Normalize.NzNfc(tt, 0, emon.Port.CellsLen(tt), text, tmp, Normalize.NzFlagLigatures() + Normalize.NzFlagRadicals());
                Model.LedgerSetText(ledger, lr, t0, emon.Port.CellsLen(text) - t0);
                rows += 1;
                i = j;
            }
        }
        return rows;
    }
    internal static int ArTagApply(emon.Port.Cells nodes, int n, int allocr, int suspect, int onlyc, int lowc, int conf) {
        // Provenance of one node: `ocr` is added to its source (`text` leaves it when every word was OCR's), the flags and the confidence.
        int s = Model.NodeSrc(nodes, n);
        if (allocr == 1) {
            if ((s & Model.SrText()) != 0) {
                Model.NodeSetSrc(nodes, n, s - Model.SrText());
            }
            Model.NodeAddSrc(nodes, n, Model.SrOcr());
        } else {
            Model.NodeAddSrc(nodes, n, Model.SrOcr());
        }
        if (suspect == 1) {
            Model.NodeAddFlag(nodes, n, Model.FlTextLayerSuspect());
        }
        if (onlyc == 1) {
            Model.NodeAddFlag(nodes, n, Model.FlOcrOnly());
        }
        if (lowc == 1) {
            Model.NodeAddFlag(nodes, n, Model.FlLowConf());
        }
        if ((conf >= 0) && ((Model.NodeConf(nodes, n) < 0) || (conf < Model.NodeConf(nodes, n)))) {
            Model.NodeSetConf(nodes, n, conf);
        }
        return 0;
    }
    public static int ArTag(emon.Port.Cells nodes, emon.Port.Cells regions, emon.Port.Cells nfw, emon.Port.Cells fv) {
        // The Model's provenance, after the paragraphs are built, from the fused flow's verdicts (`fv`, one row a word of `nfw`). A LEAF BLOCK
        // (a block that has an inline child or a text run of its own) is judged by the words whose centre lies in its region on its page: when OCR won any of
        // them its source gets `ocr` (and loses `text` when OCR won all of them), `text-layer-suspect` when OCR replaced a text-layer
        // word, `ocr-only` when OCR won all and one of them was admitted from OCR alone, `low-conf` when a verdict was; its inlines
        // follow, and its confidence is lowered to the mean of the OCR words' when they won all. A block no OCR word touched is not
        // changed: the Model of a page where the text layer won everywhere is the text layer's, byte for byte. (A block is the grain
        // because paragraph building does not carry a word's source into the node; D259.) Answers the blocks tagged.
        int nn = Model.NodeCount(nodes);
        int nw = Player.FwCount(nfw);
        int n = 1;
        int c = 0;
        int inl = 0;
        int rg = 0;
        int page = 0;
        int w = 0;
        int cx = 0;
        int cy = 0;
        int total = 0;
        int nocr = 0;
        int nsus = 0;
        int nonly = 0;
        int nlow = 0;
        int csum = 0;
        int any = 0;
        int tagged = 0;
        int conf = -1;
        int allocr = 0;
        int suspect = 0;
        int onlyc = 0;
        int lowc = 0;
        w = 0;
        while (w < nw) {
            if (emon.Port.CellsAt(fv, (w * 8) + 1) == Model.SrOcr()) {
                any = 1;
            }
            w += 1;
        }
        if (any == 0) {
            return 0;
        }
        while (n < nn) {
            if ((Model.NodeIsInline(nodes, n) == 0) && (Model.NodeRegionCount(nodes, n) > 0)) {
                inl = 0;
                c = Model.NodeFirstChild(nodes, n);
                while (c >= 0) {
                    if (Model.NodeIsInline(nodes, c) == 1) {
                        inl = 1;
                    }
                    c = Model.NodeNext(nodes, c);
                }
                if (Model.NodeHasText(nodes, n) == 1) {
                    inl = 1;
                }
                if (inl == 1) {
                    total = 0;
                    nocr = 0;
                    nsus = 0;
                    nonly = 0;
                    nlow = 0;
                    csum = 0;
                    rg = Model.NodeRegionHead(nodes, n);
                    while (rg >= 0) {
                        page = Model.RegionPage(regions, rg);
                        w = 0;
                        while (w < nw) {
                            if (emon.Port.CellsAt(nfw, w * 24) == page) {
                                cx = (emon.Port.CellsAt(nfw, (w * 24) + 1) + emon.Port.CellsAt(nfw, (w * 24) + 3)) / 2;
                                cy = (emon.Port.CellsAt(nfw, (w * 24) + 2) + emon.Port.CellsAt(nfw, (w * 24) + 4)) / 2;
                                if ((cx >= Model.RegionX0(regions, rg)) && ((cx <= Model.RegionX1(regions, rg)) && ((cy >= Model.RegionY0(regions, rg)) && (cy <= Model.RegionY1(regions, rg))))) {
                                    total += 1;
                                    if (emon.Port.CellsAt(fv, (w * 8) + 1) == Model.SrOcr()) {
                                        nocr += 1;
                                        csum += emon.Port.CellsAt(fv, (w * 8) + 3);
                                        if ((emon.Port.CellsAt(fv, (w * 8) + 4) & Model.FlTextLayerSuspect()) != 0) {
                                            nsus += 1;
                                        }
                                        if ((emon.Port.CellsAt(fv, (w * 8) + 4) & Model.FlOcrOnly()) != 0) {
                                            nonly += 1;
                                        }
                                        if ((emon.Port.CellsAt(fv, (w * 8) + 4) & Model.FlLowConf()) != 0) {
                                            nlow += 1;
                                        }
                                    } else if ((emon.Port.CellsAt(fv, (w * 8) + 4) & Model.FlLowConf()) != 0) {
                                        nlow += 1;
                                    }
                                }
                            }
                            w += 1;
                        }
                        rg = Model.RegionNext(regions, rg);
                    }
                    if (nocr > 0) {
                        allocr = 0;
                        conf = -1;
                        if (nocr == total) {
                            allocr = 1;
                            conf = csum / nocr;
                        }
                        suspect = 0;
                        if (nsus > 0) {
                            suspect = 1;
                        }
                        onlyc = 0;
                        if ((allocr == 1) && (nonly > 0)) {
                            onlyc = 1;
                        }
                        lowc = 0;
                        if (nlow > 0) {
                            lowc = 1;
                        }
                        ArTagApply(nodes, n, allocr, suspect, onlyc, lowc, conf);
                        c = Model.NodeFirstChild(nodes, n);
                        while (c >= 0) {
                            if (Model.NodeIsInline(nodes, c) == 1) {
                                ArTagApply(nodes, c, allocr, suspect, onlyc, lowc, conf);
                            }
                            c = Model.NodeNext(nodes, c);
                        }
                        tagged += 1;
                    }
                }
            }
            n += 1;
        }
        return tagged;
    }
}
